import { describe, expect, it } from "vitest";

import type { GraphData, SearchIndex, SearchService } from "../contract";
import type { GraphIndex, WalkOptions } from "./graph";
import { buildNeighborhood, indexGraph, neighbours, serviceNames } from "./graph";
import fixture from "./graph-fixture.json";
import { layoutModel } from "./layout";

// Generated by tests/fixtures/test_explorer_graph.py from synthetic packages, with the
// members `analyze --target-service X --dependency-depth N` publishes for each case.
const index = indexGraph(fixture.graph as GraphData, fixture.search as SearchIndex);
const node = (name: string): number => {
  const service = index.services.findIndex((item) => item.name === name);
  if (service < 0) throw new Error(name);
  return service;
};
const open: WalkOptions = {
  depth: Infinity,
  direction: "callees",
  maxNodes: Infinity,
  maxPerNode: Infinity,
  platform: true,
};

describe("buildNeighborhood", () => {
  it("reaches exactly the services focused publication reaches", () => {
    for (const { focal, depth, members } of fixture.cases) {
      const model = buildNeighborhood(index, node(focal), { ...open, depth: depth ?? Infinity });
      expect([focal, depth, serviceNames(index, model)]).toEqual([focal, depth, members]);
    }
  });

  it("shows only the focal service at depth 0", () => {
    const model = buildNeighborhood(index, node("orders.api:createOrder"), { ...open, depth: 0 });
    expect(model.nodes.map((item) => item.key)).toEqual([
      `n${String(node("orders.api:createOrder"))}`,
    ]);
    expect(model.edges).toEqual([]);
  });

  it("walks callers through incoming edges and callees through outgoing ones", () => {
    const hub = node("common.error:handleError");
    const callers = buildNeighborhood(index, hub, { ...open, depth: 1, direction: "callers" });
    const expected = index.incoming[hub]?.length ?? 0;
    expect(
      callers.nodes.filter((item) => item.type === "node" && item.side === "caller"),
    ).toHaveLength(expected);
    const both = buildNeighborhood(index, node("orders.api:createOrder"), {
      ...open,
      depth: 1,
      direction: "both",
    });
    const sides = new Set(both.nodes.map((item) => (item.type === "node" ? item.side : "more")));
    expect(sides).toEqual(new Set(["focal", "caller", "callee"]));
  });

  it("caps new neighbours per node with one '+N more' node, deterministically", () => {
    const hub = node("common.error:handleError");
    const total = neighbours(index, hub, "callers", true).length;
    const model = buildNeighborhood(index, hub, {
      ...open,
      depth: 1,
      direction: "callers",
      maxPerNode: 5,
    });
    const callers = model.nodes.filter((item) => item.type === "node" && item.side === "caller");
    expect(callers).toHaveLength(5);
    expect(model.nodes.find((item) => item.type === "more")).toMatchObject({
      hidden: total - 5,
      side: "caller",
    });
    const names = callers.map((item) => (item.type === "node" ? index.name(item.node) : ""));
    expect(names).toEqual(
      [...names].sort((a, b) => a.toLowerCase().localeCompare(b.toLowerCase())),
    );
    expect(
      buildNeighborhood(index, hub, { ...open, depth: 1, direction: "callers", maxPerNode: 5 }),
    ).toEqual(model);
  });

  it("never shows more nodes than the limit", () => {
    const model = buildNeighborhood(index, node("demo001.flows:step000"), { ...open, maxNodes: 6 });
    expect(model.nodes.filter((item) => item.type === "node")).toHaveLength(6);
    expect(model.limitReached).toBe(true);
  });

  it("hides built-in services unless asked, and keeps other targets as leaves", () => {
    const focal = node("orders.api:createOrder");
    const shown = (platform: boolean) =>
      buildNeighborhood(index, focal, { ...open, depth: 1, platform })
        .nodes.filter((item) => item.type === "node")
        .map((item) => (item.type === "node" ? index.name(item.node) : ""));
    expect(shown(true)).toContain("pub.client:http");
    expect(shown(false)).not.toContain("pub.client:http");
    expect(shown(false)).toContain("billing.api:postInvoice");
    const routing = buildNeighborhood(index, node("orders.api.routing:routeOrder"), {
      ...open,
      depth: 3,
    });
    const dynamic = routing.nodes.find(
      (item) => item.type === "node" && index.name(item.node) === "<dynamic-target>",
    );
    expect(dynamic).toMatchObject({ expandable: false });
  });

  it("expanding and collapsing a node returns the same model", () => {
    const focal = node("orders.api:createOrder");
    const base = buildNeighborhood(index, focal, { ...open, depth: 1 });
    const validate = node("orders.api:validateOrder");
    expect(base.nodes.find((item) => item.type === "node" && item.node === validate)).toMatchObject(
      {
        expandable: true,
        expanded: false,
      },
    );
    const opened = buildNeighborhood(index, focal, {
      ...open,
      depth: 1,
      expanded: new Set([validate]),
    });
    const names = opened.nodes.map((item) =>
      item.type === "node" ? index.name(item.node) : item.key,
    );
    expect(names).toContain("common.util:transformOrder");
    expect(buildNeighborhood(index, focal, { ...open, depth: 1, expanded: new Set() })).toEqual(
      base,
    );
  });
});

describe("layoutModel", () => {
  it("puts callers left of the focal service and callees right, the same way every time", () => {
    const focal = node("orders.api:createOrder");
    const model = buildNeighborhood(index, focal, { ...open, depth: 1, direction: "both" });
    const label = (key: string) => key;
    const boxes = layoutModel(model, label);
    const x = (key: string) => boxes.get(key)?.x ?? Number.NaN;
    const focalX = x(`n${String(focal)}`);
    for (const item of model.nodes) {
      if (item.type !== "node" || item.side === "focal") continue;
      if (item.side === "caller") expect(x(item.key)).toBeLessThan(focalX);
      else expect(x(item.key)).toBeGreaterThan(focalX);
    }
    expect(layoutModel(model, label)).toEqual(boxes);
  });
});

describe("at production size", () => {
  const big = syntheticIndex(7300, 25000);

  it("builds a neighbourhood in well under 50 ms", () => {
    const started = performance.now();
    for (let focal = 0; focal < 20; focal += 1) {
      buildNeighborhood(big, focal * 300, {
        ...open,
        depth: 4,
        direction: "both",
        maxNodes: 300,
        maxPerNode: 25,
      });
    }
    expect((performance.now() - started) / 20).toBeLessThan(50);
  });

  it("lays out the largest allowed graph (300 nodes) in under a second", () => {
    const model = buildNeighborhood(big, 0, {
      ...open,
      depth: 6,
      direction: "both",
      maxNodes: 300,
      maxPerNode: 25,
    });
    expect(model.nodes.filter((item) => item.type === "node").length).toBeGreaterThan(200);
    const started = performance.now();
    layoutModel(model, (key) => `service.namespace.part:${key}`);
    expect(performance.now() - started).toBeLessThan(1000);
  });
});

function syntheticIndex(services: number, edges: number): GraphIndex {
  const entries: SearchService[] = Array.from({ length: services }, (_, i) => ({
    id: i.toString(16).padStart(16, "0"),
    name: `pkg${String(i % 200)}.flows:service${String(i)}`,
    package: `Pkg${String(i % 200)}`,
    kind: "flow",
    analysis: "full",
    description: "none",
    purpose: null,
  }));
  let seed = 7;
  const random = (limit: number): number => {
    seed = (seed * 1103515245 + 12345) % 2147483648;
    return seed % limit;
  };
  const graph: GraphData = {
    contract: "wm-doc-explorer.v1",
    services: entries.map((entry) => entry.id),
    targets: [{ name: "pub.flow:debugLog", status: "platform", note: null }],
    edges: Array.from({ length: edges }, (_, i) => {
      const source = random(services);
      // a few hubs, like real error handlers and loggers
      const target = i % 10 === 0 ? random(20) : i % 13 === 0 ? services : random(services);
      return [source, target, "invokes", 1] as [number, number, "invokes", number];
    }),
  };
  return indexGraph(graph, { contract: "wm-doc-explorer.v1", services: entries, packages: [] });
}
